code:
// JavaScript allows silent runtime bugs:
function getArea(width, height) {
  return width * height;
}
getArea("10", "20"); // Works by coercion
getArea(10); // Returns NaN silently!

// TypeScript catches these at compile-time:
function getAreaTS(width: number, height: number): number {
  return width * height;
}
// getAreaTS(10); // Error: Expected 2 arguments, but got 1.

// Compilation Pipeline:
// Source Code (.ts)
//      ↓ Scanner
//    Tokens
//      ↓ Parser
//     AST (Abstract Syntax Tree)
//      ↓ Binder
//    Symbols & Scopes
//      ↓ Type Checker
//    Diagnostics (Errors & Warnings)
//      ↓ Emitter
// Output Code (.js) + Declarations (.d.ts) + SourceMaps (.js.map)

// All standard ECMAScript is valid TS:
const sum = (a, b) => a + b;
const user = { name: "Alex", loggedIn: true };

// TypeScript extends this syntax by adding type annotations:
const typedSum = (a: number, b: number): number => a + b;

// Static typing checked at compile-time:
let message: string = "Hello";
// message = 42; // TypeScript Error: Type 'number' is not assignable to type 'string'.

// But at runtime (in Node or browser), it is pure dynamic JavaScript:
// typeof message can be anything if unvalidated data was coerced or cast.

// Escape hatches weaken type guarantees:
let data: any = "hello";
data.nonExistentMethod(); // Compiles cleanly, throws TypeError at runtime!

// Type assertion bypass:
const num = ("123" as unknown) as number;
// num is string at runtime, causing potential NaN in math operations

interface Point2D {
  x: number;
  y: number;
}

interface Vector2D {
  x: number;
  y: number;
}

let p: Point2D = { x: 10, y: 20 };
let v: Vector2D = p; // Completely valid! Both have shape { x: number, y: number }

// In Java/C#, this would fail without explicit inheritance.
// In TypeScript, this succeeds due to structural typing:
class OrderId {
  constructor(public value: string) {}
}

class UserId {
  constructor(public value: string) {}
}

let user: UserId = new OrderId("ord-123"); // TypeScript allows this! Both are { value: string }

interface Pet {
  name: string;
}

interface Dog {
  name: string;
  breed: string;
}

let dog: Dog = { name: "Rex", breed: "German Shepherd" };
let pet: Pet = dog; // OK: Dog has required property 'name'

// pet = dog works, but dog = pet fails because 'breed' is missing:
// let invalid: Dog = pet; // Error: Property 'breed' is missing in type 'Pet'.

let count = 10; // Inferred as number
let items = [1, 2, "three"]; // Inferred as (string | number)[]

function multiply(a: number, b: number) {
  return a * b; // Inferred return type: number
}

// Contextual typing infers callback parameter 'event':
window.onmousedown = function (event) {
