  // console.log(event.kangaroo); // Error: Property 'kangaroo' does not exist on 'MouseEvent'.
};

const numbers = [10, 20, 30];
numbers.map((val) => val * 2); // 'val' contextually typed as number

const x = "hello"; // Type: literal "hello" (cannot be reassigned)
let y = "hello";   // Type: widened to string (can be reassigned to any string)

// Object property widening:
const config = {
  status: "success", // Inferred as string, not literal "success"!
};

// Prevent widening using 'as const':
const lockedConfig = {
  status: "success",
