// TypeScript input (50 lines of complex types & generics):
type DeepImmutable<T> = ...;
function processData<T extends object>(data: T): DeepImmutable<T> {
  return Object.freeze(data) as any;
}

// Compiled JavaScript output (3 lines, zero type overhead):
function processData(data) {
  return Object.freeze(data);
}

