type NetworkState =
  | { state: "idle" }
  | { state: "loading" }
  | { state: "success"; data: string[] }
  | { state: "error"; error: Error };

function render(s: NetworkState) {
  switch (s.state) {
    case "loading": return "Loading spinner...";
    case "success": return s.data.join(", "); // s.data is safely accessible!
    case "error": return `Error: ${s.error.message}`;
    case "idle": return "Ready";
  }
}

