function mapList<T, U>(items: T[], transform: (item: T, index: number) => U): U[] {
  const result: U[] = [];
  for (let i = 0; i < items.length; i++) {
    result.push(transform(items[i], i));
  }
  return result;
}

// Inferred: T = string, U = number
const lengths = mapList(["apple", "banana"], (fruit) => fruit.length);
console.log(lengths); // number[]

