  user: AuthenticatedUser;
}

// Guard middleware with type narrowing:
export function authMiddleware(req: Request, res: Response, next: NextFunction) {
  const token = req.headers.authorization;
  if (!token) return res.status(401).json({ error: "Unauthorized" });

  // Verify token and attach user
  (req as AuthenticatedRequest).user = { id: "u1", tenantId: "t1", role: "admin" };
  next();
}

// Controller strictly expects AuthenticatedRequest:
export const profileController = (req: AuthenticatedRequest, res: Response) => {
  console.log(req.user.tenantId); // Guaranteed defined without optional chaining!
};

import { ErrorRequestHandler } from "express";

export class AppError extends Error {
  constructor(public statusCode: number, message: string) {
    super(message);
  }
}

export const errorHandler: ErrorRequestHandler = (err, req, res, next) => {
  const statusCode = err instanceof AppError ? err.statusCode : 500;
  const message = err.message || "Internal Server Error";

  console.error(`[Error] ${req.method} ${req.url}:`, err);
  res.status(statusCode).json({
    success: false,
    error: { message, statusCode },
  });
};

export type ApiResponse<T> =
  | {
      success: true;
      statusCode: number;
      data: T;
      meta?: { page?: number; total?: number };
    }
  | {
      success: false;
      statusCode: number;
      error: {
        code: string;
        message: string;
        details?: unknown;
      };
    };

export function sendSuccess<T>(res: Response, data: T, statusCode = 200) {
  res.status(statusCode).json({ success: true, statusCode, data });
}

import { z } from "zod";
import { Request, Response, NextFunction } from "express";

export const CreateUserSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
  age: z.number().int().positive().optional(),
});

export const validateBody = (schema: z.ZodSchema) => {
  return (req: Request, res: Response, next: NextFunction) => {
    try {
      req.body = schema.parse(req.body); // Validates AND sanitizes
      next();
    } catch (err) {
      if (err instanceof z.ZodError) {
        res.status(400).json({ success: false, errors: err.errors });
        return;
      }
      next(err);
    }
  };
};

