interface PaginationQuery {
  page?: number;
  limit?: number;
  sortBy?: string;
  sortOrder?: "asc" | "desc";
}

interface PaginatedResult<T> {
  items: T[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
  hasNext: boolean;
}

function paginate<T>(items: T[], total: number, query: PaginationQuery): PaginatedResult<T> {
  const page = query.page || 1;
  const limit = query.limit || 10;
  return {
    items,
    total,
    page,
    limit,
    totalPages: Math.ceil(total / limit),
    hasNext: page * limit < total,
  };
}

interface IRepository<T extends { id: ID }, ID> {
  findById(id: ID): Promise<T | null>;
  create(item: Omit<T, "id">): Promise<T>;
  delete(id: ID): Promise<boolean>;
}

class InMemoryRepo<T extends { id: string }> implements IRepository<T, string> {
  private store = new Map<string, T>();

  async findById(id: string): Promise<T | null> {
    return this.store.get(id) || null;
  }
  async create(item: Omit<T, "id">): Promise<T> {
    const id = Math.random().toString(36).substring(7);
    const entity = { ...item, id } as T;
    this.store.set(id, entity);
    return entity;
  }
  async delete(id: string): Promise<boolean> {
    return this.store.delete(id);
  }
}

