type PaymentMethod =
  | { provider: "credit_card"; cardNumber: string; cvv: string }
  | { provider: "paypal"; email: string }
  | { provider: "crypto"; walletAddress: string; network: "ETH" | "BTC" };

function processPayment(payment: PaymentMethod, amountCents: number): string {
  switch (payment.provider) {
    case "credit_card":
      return `Charged $${amountCents / 100} to card ending in ${payment.cardNumber.slice(-4)}`;
    case "paypal":
      return `Invoiced $${amountCents / 100} to PayPal: ${payment.email}`;
    case "crypto":
      return `Sent ${amountCents} satoshis to ${payment.network} wallet ${payment.walletAddress}`;
    default: {
      const _exhaustive: never = payment;
      throw new Error(`Unhandled provider: ${_exhaustive}`);
    }
  }
}

