type HttpMethod = "GET" | "POST" | "PUT";

function handleMethod(method: HttpMethod) {
  switch (method) {
    case "GET": return "Reading";
    case "POST": return "Creating";
    case "PUT": return "Updating";
    default: return assertNever(method);
  }
}

async function retry<T>(
  task: () => Promise<T>,
  retries: number = 3,
  delayMs: number = 500
): Promise<T> {
  try {
    return await task();
  } catch (err) {
    if (retries <= 1) throw err;
    await new Promise((r) => setTimeout(r, delayMs));
    return retry(task, retries - 1, delayMs * 2);
  }
}

