type Middleware<TIn, TOut> = (ctx: TIn) => Promise<TOut> | TOut;

class Pipeline<TContext extends object> {
  constructor(private fns: ((ctx: any) => any)[] = []) {}

  use<TNext extends object>(
    fn: Middleware<TContext, TNext>
  ): Pipeline<TContext & TNext> {
    return new Pipeline([...this.fns, fn]);
  }

  async execute(initialContext: TContext): Promise<any> {
    let current = { ...initialContext };
    for (const fn of this.fns) {
      const result = await fn(current);
      current = { ...current, ...result };
    }
    return current;
  }
}

// Usage:
